import{_ as t,o as i,c as o,a0 as s}from"./chunks/framework.Bmhw_dvp.js";const g=JSON.parse('{"title":"E2E Use Cases & Test Definitions","description":"The single source of truth for all Playwright End-to-End tests implemented in the Sanjeev AI frontend.","frontmatter":{"isInternal":true,"type":"Testing","title":"E2E Use Cases & Test Definitions","description":"The single source of truth for all Playwright End-to-End tests implemented in the Sanjeev AI frontend.","tags":["testing","e2e","playwright","qa"]},"headers":[],"relativePath":"testing/e2e-use-cases.md","filePath":"testing/e2e-use-cases.md"}'),a={name:"testing/e2e-use-cases.md"};function r(n,e,l,c,d,u){return i(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="end-to-end-e2e-use-cases" tabindex="-1">End-to-End (E2E) Use Cases <a class="header-anchor" href="#end-to-end-e2e-use-cases" aria-label="Permalink to &quot;End-to-End (E2E) Use Cases&quot;">​</a></h1><p>This document strictly defines the E2E use cases that are covered by our Playwright test suite (<code>frontend/e2e/</code>).</p><p><strong>Document-First Approach:</strong> Any new feature that requires E2E coverage MUST be documented here as a use case <em>before</em> the Playwright test is written or updated. This ensures our tests accurately reflect intended user behavior.</p><h2 id="core-workflows" tabindex="-1">Core Workflows <a class="header-anchor" href="#core-workflows" aria-label="Permalink to &quot;Core Workflows&quot;">​</a></h2><h3 id="_1-dashboard-navigation-dashboard-spec-ts" tabindex="-1">1. Dashboard Navigation (<code>dashboard.spec.ts</code>) <a class="header-anchor" href="#_1-dashboard-navigation-dashboard-spec-ts" aria-label="Permalink to &quot;1. Dashboard Navigation (`dashboard.spec.ts`)&quot;">​</a></h3><p><strong>Objective:</strong> Verify that a user can successfully log in, access the dashboard, and create a basic project.</p><ul><li><strong>Pre-conditions:</strong> User is unauthenticated.</li><li><strong>Steps:</strong><ol><li>User navigates to the application root (<code>/</code>).</li><li>User clicks &quot;Sign in with Google&quot; and completes the Firebase Auth Emulator flow (or uses custom token in staging).</li><li>User verifies they are redirected to the main dashboard displaying &quot;Your Projects&quot;.</li><li>User enters a project name in the &quot;Create Workspace&quot; input and submits.</li><li>User clicks the newly created project card in the grid.</li></ol></li><li><strong>Expected Outcome:</strong> User is successfully redirected to the &quot;Project Dashboard&quot; view for the specific project.</li></ul><h3 id="_2-project-modals-script-parsing-project-modals-spec-ts" tabindex="-1">2. Project Modals &amp; Script Parsing (<code>project-modals.spec.ts</code>) <a class="header-anchor" href="#_2-project-modals-script-parsing-project-modals-spec-ts" aria-label="Permalink to &quot;2. Project Modals &amp; Script Parsing (`project-modals.spec.ts`)&quot;">​</a></h3><p><strong>Objective:</strong> Verify that users can edit project metadata and ingest a raw script using the &quot;Paste Script&quot; modal, bypassing the standard blank script flow.</p><ul><li><strong>Pre-conditions:</strong> User is logged in.</li><li><strong>Steps:</strong><ol><li>User creates a new project and navigates to the Project Dashboard.</li><li>User clicks the &quot;Settings&quot; button to open the Project Settings Modal.</li><li>User updates the project name and description, and clicks &quot;Save Settings&quot;.</li><li>User verifies the updated name appears in the header.</li><li>User clicks &quot;Paste Text&quot; to open the Paste Script Modal.</li><li>User inputs a title (e.g., &quot;Episode 1: The Beginning&quot;) and raw script text (e.g., &quot;INT. COFFEE SHOP...&quot;).</li><li>User clicks &quot;Create Script&quot; and waits for the &quot;Analyzing...&quot; status to complete.</li></ol></li><li><strong>Expected Outcome:</strong> The parser successfully processes the text, the modal closes, and the user is redirected into the Unified Studio with the correct script title displayed in the header.</li><li><strong>Environment Note:</strong> AI responses are mocked in <code>local/dev</code> but hit real endpoints in <code>staging</code>.</li></ul><h3 id="_3-full-orchestrator-workflow-studio-orchestrator-spec-ts" tabindex="-1">3. Full Orchestrator Workflow (<code>studio-orchestrator.spec.ts</code>) <a class="header-anchor" href="#_3-full-orchestrator-workflow-studio-orchestrator-spec-ts" aria-label="Permalink to &quot;3. Full Orchestrator Workflow (`studio-orchestrator.spec.ts`)&quot;">​</a></h3><p><strong>Objective:</strong> Verify the entire end-to-end automation workflow from a blank script all the way to a rendered video, ensuring human-in-the-loop approvals function correctly.</p><ul><li><strong>Pre-conditions:</strong> User is logged in and inside the Unified Studio for a newly generated script.</li><li><strong>Steps:</strong><ol><li>User clicks the &quot;Automate Workflow&quot; button and selects &quot;Guided Mode&quot;.</li><li>User approves <code>step_scenes</code>. System mocks/runs director generation.</li><li>User approves <code>step_audio</code>. System mocks/runs ElevenLabs voiceover generation.</li><li>User approves <code>step_visuals</code>. System mocks/runs Imagen generation for scenes.</li><li>User approves <code>step_video</code>. System mocks/runs FFmpeg stitching.</li><li>User verifies the &quot;Final Render&quot; video player appears in Cinema Mode.</li></ol></li><li><strong>Expected Outcome:</strong> The stepper successfully advances through all stages, properly gating execution behind user approval clicks.</li></ul><h3 id="_4-youtube-publishing-editor-studio-publishing-spec-ts" tabindex="-1">4. YouTube Publishing &amp; Editor (<code>studio-publishing.spec.ts</code>) <a class="header-anchor" href="#_4-youtube-publishing-editor-studio-publishing-spec-ts" aria-label="Permalink to &quot;4. YouTube Publishing &amp; Editor (`studio-publishing.spec.ts`)&quot;">​</a></h3><p><strong>Objective:</strong> Verify that a user can edit YouTube metadata and publish a finalized video directly to YouTube.</p><ul><li><strong>Pre-conditions:</strong> User is logged in with a linked YouTube account.</li><li><strong>Environment Note:</strong> Real external API tests run ONLY in the <code>staging</code> environment.</li><li><strong>Steps:</strong><ol><li>User waits for the Orchestrator to reach <code>step_publish</code>.</li><li>User clicks &quot;Open Metadata Editor&quot;.</li><li>User edits the title, description, and tags, then clicks &quot;Approve Metadata&quot;.</li><li>System queues the publish action.</li></ol></li><li><strong>Expected Outcome:</strong> The video payload is transmitted to the backend orchestrator successfully, and the UI displays a success toast.</li></ul><h2 id="manual-studio-operations-studio-manual-spec-ts" tabindex="-1">Manual Studio Operations (<code>studio-manual.spec.ts</code>) <a class="header-anchor" href="#manual-studio-operations-studio-manual-spec-ts" aria-label="Permalink to &quot;Manual Studio Operations (`studio-manual.spec.ts`)&quot;">​</a></h2><p>These tests verify the granular, manual controls within the Unified Studio, bypassing the automated orchestrator.</p><h3 id="_5-cast-location-management" tabindex="-1">5. Cast &amp; Location Management <a class="header-anchor" href="#_5-cast-location-management" aria-label="Permalink to &quot;5. Cast &amp; Location Management&quot;">​</a></h3><p><strong>Objective:</strong> Verify that users can manually configure the <code>vibeMap</code> for characters and locations.</p><ul><li><strong>Pre-conditions:</strong> User is logged in with an active script.</li><li><strong>Steps:</strong><ol><li>User opens the &quot;Cast &amp; Locations&quot; modal from the Studio Header.</li><li>User edits the physical description prompt for a character.</li><li>User clicks &quot;Generate Character Image&quot; (AI image generation is mocked).</li><li>User verifies the character thumbnail updates in the modal and timeline.</li><li>User assigns a specific ElevenLabs voice ID to the character.</li><li>User clicks &quot;Preview Voice&quot; and verifies audio playback is triggered.</li></ol></li></ul><h3 id="_6-scene-visual-generation" tabindex="-1">6. Scene &amp; Visual Generation <a class="header-anchor" href="#_6-scene-visual-generation" aria-label="Permalink to &quot;6. Scene &amp; Visual Generation&quot;">​</a></h3><p><strong>Objective:</strong> Verify that users can manually create scenes and generate individual visual assets.</p><ul><li><strong>Pre-conditions:</strong> User has a raw script with no scenes.</li><li><strong>Steps:</strong><ol><li>User clicks &quot;Run Director&quot; to manually break the script into scenes.</li><li>User selects a scene in the timeline.</li><li>User clicks &quot;Generate Image&quot; in the Visual Stage (Imagen generation is mocked).</li><li>User verifies the scene card updates with the new image.</li><li>User toggles the Visual Stage to &quot;Video Mode&quot;.</li><li>User clicks &quot;Generate Video&quot; for the same scene (Gemini/Kling generation is mocked).</li><li>User verifies the scene card updates with a video player.</li></ol></li></ul><h3 id="_7-manual-audio-video-rendering" tabindex="-1">7. Manual Audio &amp; Video Rendering <a class="header-anchor" href="#_7-manual-audio-video-rendering" aria-label="Permalink to &quot;7. Manual Audio &amp; Video Rendering&quot;">​</a></h3><p><strong>Objective:</strong> Verify the manual export and stitching flow.</p><ul><li><strong>Pre-conditions:</strong> User has scenes, visuals, and voice configurations ready.</li><li><strong>Steps:</strong><ol><li>User clicks &quot;Generate Audio&quot; in the Studio Toolbar to render the full timeline voiceover.</li><li>User clicks &quot;Export Video&quot; in the Studio Toolbar.</li><li>User waits for the export progress bar to complete (FFmpeg stitching is mocked).</li><li>User switches view mode to &quot;Cinema&quot;.</li><li>User verifies the &quot;Final Render&quot; video player appears and plays back the stitched video.</li></ol></li></ul><h2 id="failure-edge-case-workflows" tabindex="-1">Failure &amp; Edge Case Workflows <a class="header-anchor" href="#failure-edge-case-workflows" aria-label="Permalink to &quot;Failure &amp; Edge Case Workflows&quot;">​</a></h2><h3 id="_5-critical-api-billing-limits-failure-states-spec-ts" tabindex="-1">5. Critical API &amp; Billing Limits (<code>failure-states.spec.ts</code>) <a class="header-anchor" href="#_5-critical-api-billing-limits-failure-states-spec-ts" aria-label="Permalink to &quot;5. Critical API &amp; Billing Limits (`failure-states.spec.ts`)&quot;">​</a></h3><p><strong>Objective:</strong> Ensure the platform degrades gracefully and informs the user when critical external dependencies fail or quota is exceeded.</p><ul><li><strong>Pre-conditions:</strong> User is logged in with a mock account configured to simulate failures.</li><li><strong>Steps:</strong><ol><li><strong>Billing Limit:</strong> User attempts to run an Automation, but their mock account has 0 credits. Verify the UI displays an &quot;Insufficient Credits&quot; modal.</li><li><strong>YouTube API Timeout:</strong> User attempts to publish, but the mocked YouTube API returns a 504 Timeout. Verify the UI displays a contextual error message allowing retry, rather than hanging indefinitely.</li></ol></li><li><strong>Expected Outcome:</strong> Clear error boundaries prevent silent failures.</li></ul><h3 id="_6-client-side-error-logging-error-logging-spec-ts" tabindex="-1">6. Client-Side Error Logging (<code>error-logging.spec.ts</code>) <a class="header-anchor" href="#_6-client-side-error-logging-error-logging-spec-ts" aria-label="Permalink to &quot;6. Client-Side Error Logging (`error-logging.spec.ts`)&quot;">​</a></h3><p><strong>Objective:</strong> Ensure that unhandled exceptions and captured client-side errors are correctly formatted and sent to the Cloud Logging integration.</p><ul><li><strong>Pre-conditions:</strong> User is interacting with the application in an environment configured with a mocked Cloud Logging endpoint.</li><li><strong>Steps:</strong><ol><li>User performs an action that triggers a simulated error (e.g., clicking a hidden &quot;Force Error&quot; debug button or simulating a failed fetch response).</li><li>Verify that the UI displays a generic fallback error boundary or toast notification to the user.</li><li>Verify that an HTTP request (or Firebase function call) is dispatched to the Cloud Logging integration containing the correct structured payload (error message, stack trace, user ID).</li></ol></li><li><strong>Expected Outcome:</strong> Errors are gracefully caught and transmitted to the logging service without exposing sensitive stack traces to the end-user.</li></ul>',34)])])}const p=t(a,[["render",r]]);export{g as __pageData,p as default};
